'use strict';
const speakingTypes=['日常口语','雅思 Part 1','雅思 Part 2','雅思 Part 3','朗读 / 跟读'];
const speakingStarters=[
 {title:'介绍一件最近在学的事',type:'日常口语',prompt:'What are you learning at the moment? Explain why you chose it and what you find difficult.',seconds:90},
 {title:'日常学习习惯',type:'雅思 Part 1',prompt:'Do you prefer studying alone or with other people? Why?',seconds:45},
 {title:'一次难忘的旅行',type:'雅思 Part 2',prompt:'Describe a trip you remember well. Say where you went, who you went with, what you did, and why you remember it.',seconds:120},
 {title:'旅行与理解文化',type:'雅思 Part 3',prompt:'How can travel change the way people understand other cultures?',seconds:90}
];
function normalizePractice(){db.practice??={version:1,songs:[],prompts:[],drafts:{},metronome:{bpm:80,beats:4,subdivision:1,volume:0.35}};}
normalizePractice();
Object.assign(labels,{guitarChords:'和弦速记',guitarBasics:'吉他基础',guitarPractice:'吉他练习',englishPractice:'口语练习'});
let practiceSongId=null,practiceSegmentId=null,practicePromptId=null,practiceDraftTimer=null,practiceTimer=null,practiceTimerStarted=0,practiceTimerElapsed=0,practiceSaving=false;
let capture={generation:0,state:'idle',stream:null,recorder:null,chunks:[],blob:null,url:'',started:0,seconds:0,promptId:null,error:'',timer:null};
const metro={ctx:null,generation:0,running:false,next:0,tick:0,interval:null,timeouts:new Set(),nodes:new Set(),beat:0,error:''};
const practiceAudioURLs=new Map();
const practiceSong=()=>db.practice.songs.find(s=>s.id===practiceSongId)||db.practice.songs.find(s=>!s.archived)||null;
const practicePrompt=()=>db.practice.prompts.find(p=>p.id===practicePromptId)||db.practice.prompts.find(p=>!p.archived)||null;
const practiceSegment=()=>practiceSong()?.segments.find(s=>s.id===practiceSegmentId)||null;
const practiceClock=seconds=>`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;
const practiceSessions=kind=>db.sessions.filter(s=>s.practice?.kind===kind);
window.LouiePractice={trackAction:id=>id==='guitar'?'<button class="primary" data-page="guitarBasics">吉他基础</button><button data-page="guitarChords">和弦速记</button><button onclick="openPractice(\'guitar\')">♫ 曲目与节拍器</button>':id==='english'?'<button class="primary" onclick="openPractice(\'english\')">◉ 口语练习</button>':''};
function openPractice(kind){const id=kind==='guitar'?'guitar':'english';if(!preparePracticeLeave())return;setProjectContext(id);go(id==='guitar'?'guitarPractice':'englishPractice')}
const renderBeforePractice=render;
render=function(){normalizePractice();const target=page,isPractice=['guitarChords','guitarBasics','guitarPractice','englishPractice'].includes(target);if(isPractice){page='track';renderBeforePractice();page=target;$('#crumb').textContent=labels[target];$('#view').innerHTML=target==='guitarChords'?guitarChordsView():target==='guitarBasics'?guitarBasicsView():target==='guitarPractice'?guitarPracticeView():englishPracticeView();renderPersonalNav();renderNavigationContext();updatePracticeClock();updateMetronomeBeat(metro.beat)}else renderBeforePractice()};
function preparePracticeLeave(){if(capture.state!=='idle'&&capture.state!=='error'){if(!confirm('这段录音还未保存。离开会丢弃录音，继续？'))return false;discardSpeakingRecording(true)}return true}
const openTrackBeforePractice=openTrack;openTrack=function(id){if(preparePracticeLeave())openTrackBeforePractice(id)};
const goBeforePractice=go;
go=function(target){if(target!==page){if(!preparePracticeLeave())return;stopMetronome();resetPracticeTimer();flushPracticeDraft();releasePracticeAudio()}goBeforePractice(target)};
function releasePracticeAudio(){for(const url of practiceAudioURLs.values())URL.revokeObjectURL(url);practiceAudioURLs.clear()}
function guitarPracticeView(){const song=practiceSong(),segment=practiceSegment();return `<div class="pagehead"><div><h1>吉他练习</h1></div><button class="primary" onclick="songForm()">＋ 添加曲目</button></div><div class="practice-layout"><section><div class="card"><div class="practice-select-row"><label>当前曲目<select aria-label="当前曲目" onchange="selectPracticeSong(this.value)">${db.practice.songs.filter(s=>!s.archived).map(s=>`<option value="${s.id}" ${s.id===song?.id?'selected':''}>${esc(s.title)}${s.artist?' · '+esc(s.artist):''}</option>`).join('')}</select></label>${song?`<button onclick="songForm('${song.id}')">编辑</button>`:''}</div>${song?`<div class="actions"><span class="tag">${esc(song.status)}</span>${song.materialId&&db.materials.some(m=>m.id===song.materialId)?`<button onclick="openMaterial('${song.materialId}')">打开乐谱 ↗</button>`:'<button onclick="trackLibrary(\'guitar\')">选择或收纳乐谱 ↗</button>'}</div>${song.note?`<p class="practice-note">${esc(song.note)}</p>`:''}<div class="practice-section-title"><h2>分段练习</h2><button onclick="segmentForm()">＋ 添加分段</button></div>${song.segments.length?song.segments.map(s=>`<div class="practice-segment ${segment?.id===s.id?'selected':''}"><button class="segment-pick" onclick="selectPracticeSegment('${s.id}')"><b>${esc(s.title)}</b><small>${esc(s.range||'')} · ${s.startBpm} → ${s.targetBpm} BPM</small>${s.bestBpm?`<small>已确认顺畅：${s.bestBpm} BPM</small>`:''}</button><button onclick="segmentForm('${s.id}')" aria-label="编辑${esc(s.title)}">编辑</button></div>`).join(''):'<p class="empty">把难点拆成几个小节，从能弹稳的速度开始。</p>'}`:'<p class="empty">先加一首正在练的曲子，再关联乐谱和难点段落。</p>'}</div><details class="card"><summary>已归档曲目</summary>${db.practice.songs.filter(s=>s.archived).map(s=>`<div class="row"><b>${esc(s.title)}</b><button onclick="restorePracticeItem('song','${s.id}')">恢复</button></div>`).join('')||'<p class="muted">暂无</p>'}</details></section><section><div class="card metronome"><div class="practice-section-title"><h2>节拍器</h2><span id="metroState" class="muted">${metro.running?'播放中':'已停止'}</span></div><label class="metro-tempo"><input aria-label="节拍器 BPM" type="number" min="30" max="240" step="1" value="${db.practice.metronome.bpm}" onchange="setMetronome('bpm',this.value)"><span>BPM</span></label><div class="metro-beats" id="metroBeats">${Array.from({length:db.practice.metronome.beats},(_,i)=>`<i class="${metro.running&&metro.beat===i?'on':''}"></i>`).join('')}</div><div class="formgrid"><label>每小节拍数<select aria-label="每小节拍数" onchange="setMetronome('beats',this.value)">${opts([1,2,3,4,5,6,7,8],db.practice.metronome.beats)}</select></label><label>每拍细分<select aria-label="每拍细分" onchange="setMetronome('subdivision',this.value)">${[1,2,3,4].map(n=>`<option value="${n}" ${db.practice.metronome.subdivision===n?'selected':''}>${n===1?'整拍':n+' 等分'}</option>`).join('')}</select></label></div><label>音量<input aria-label="节拍器音量" type="range" min="0" max="0.7" step="0.05" value="${db.practice.metronome.volume}" onchange="setMetronome('volume',this.value)"></label><button id="metroToggle" class="primary" onclick="toggleMetronome()">${metro.running?'停止节拍':'开始节拍'}</button>${metro.error?`<p class="practice-error">${esc(metro.error)}</p>`:''}</div><div class="card"><div class="practice-section-title"><h2>${segment?esc(segment.title):'本次练习'}</h2><b class="practice-clock" id="practiceClock">${practiceClock(practiceElapsed())}</b></div><div class="actions"><button id="practiceTimerToggle" onclick="togglePracticeTimer()">${practiceTimer?'暂停计时':'开始计时'}</button><button class="primary" onclick="guitarLogForm()" ${!song?'disabled':''}>记录本次练习</button></div><p class="muted practice-caption">${segment?`${esc(segment.range||'当前段落')} · 目标 ${segment.targetBpm} BPM`:'计时后确认实际分钟，再计入学习记录。'}</p></div></section></div>${practiceHistory('guitar',song?.id)}`}
function selectPracticeSong(id){stopPracticeTimer();resetPracticeTimer();stopMetronome();practiceSongId=id;practiceSegmentId=null;render()}
function selectPracticeSegment(id){stopMetronome();practiceSegmentId=id;db.practice.metronome.bpm=practiceSegment().startBpm;save();render()}
function songForm(id){const s=db.practice.songs.find(s=>s.id===id)||{title:'',artist:'',materialId:'',status:'练习中',note:''};show(`<h2>${id?'编辑':'添加'}曲目</h2><form id="songForm"><label>曲目名称<input name="title" maxlength="120" required value="${esc(s.title)}"></label><label>作曲 / 演奏者<input name="artist" maxlength="100" value="${esc(s.artist)}"></label><label>关联乐谱<select name="materialId"><option value="">暂不关联</option>${db.materials.filter(m=>recordTrack(m)==='guitar').map(m=>`<option value="${m.id}" ${m.id===s.materialId?'selected':''}>${esc(m.title)}</option>`).join('')}</select></label><label>状态<select name="status">${opts(['练习中','能完整演奏','暂放'],s.status)}</select></label><label>备注<textarea name="note" maxlength="2000">${esc(s.note)}</textarea></label><div class="actions"><button class="primary">保存曲目</button>${id?`<button type="button" onclick="archivePracticeItem('song','${id}')">归档</button>`:''}</div></form>`);$('#songForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),title=String(f.get('title')).trim();if(!title)return;const values={title,artist:String(f.get('artist')).trim(),materialId:f.get('materialId'),status:f.get('status'),note:String(f.get('note')).trim()};if(id)Object.assign(s,values);else{if(db.practice.songs.length>=300)return toast('曲目最多300首。');const item={id:uid(),...values,segments:[],archived:false};db.practice.songs.push(item);practiceSongId=item.id}if(await save()){closeModal();render()}}}
function segmentForm(id){const song=practiceSong();if(!song)return;const s=song.segments.find(s=>s.id===id)||{title:'',range:'',startBpm:60,targetBpm:90};show(`<h2>${id?'编辑':'添加'}分段</h2><form id="segmentForm"><label>分段名称<input name="title" required maxlength="100" value="${esc(s.title)}" placeholder="前奏 / 换和弦 / 第一次卡住的地方"></label><label>小节 / 页码范围<input name="range" maxlength="120" value="${esc(s.range)}" placeholder="第 1～8 小节，谱第 2 页"></label><div class="formgrid"><label>起始 BPM<input name="startBpm" type="number" min="30" max="240" value="${s.startBpm}" required></label><label>目标 BPM<input name="targetBpm" type="number" min="30" max="240" value="${s.targetBpm}" required></label></div><button class="primary">保存分段</button></form>`);$('#segmentForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),title=String(f.get('title')).trim(),startBpm=+f.get('startBpm'),targetBpm=+f.get('targetBpm');if(!title)return;if(!validBpm(startBpm)||!validBpm(targetBpm)||startBpm>targetBpm)return toast('速度需在30～240之间，目标不能低于起始速度。');if(id)Object.assign(s,{title,range:String(f.get('range')).trim(),startBpm,targetBpm});else{if(song.segments.length>=100)return toast('每首曲目最多100个分段。');const item={id:uid(),title,range:String(f.get('range')).trim(),startBpm,targetBpm,bestBpm:0};song.segments.push(item);practiceSegmentId=item.id}if(!id||practiceSegmentId===id){stopMetronome();db.practice.metronome.bpm=startBpm}if(await save()){closeModal();render()}}}
function guitarLogForm(){const song=practiceSong(),segment=practiceSegment();if(!song)return;stopPracticeTimer();const sessionId=uid(),seconds=practiceElapsed();show(`<h2>记录本次练习</h2><form id="guitarLogForm"><p>${esc(song.title)}${segment?' · '+esc(segment.title):' · 全曲'}</p><div class="formgrid"><label>实际分钟<input name="minutes" type="number" min="1" max="720" value="${seconds?Math.max(1,Math.round(seconds/60)):15}" required></label><label>本次 BPM<input name="bpm" type="number" min="30" max="240" value="${db.practice.metronome.bpm}" required></label></div><label class="check"><input name="clean" type="checkbox">这个速度下已能连续顺畅演奏</label><label>卡点 / 下次继续哪里<textarea name="note" maxlength="2000" placeholder="例如：第5小节换把仍卡顿，下次从55 BPM开始"></textarea></label><button class="primary">保存练习</button></form>`);$('#guitarLogForm').onsubmit=async e=>{e.preventDefault();if(practiceSaving)return;const f=new FormData(e.target),minutes=+f.get('minutes'),bpm=+f.get('bpm');if(!validBpm(bpm)||!validPracticeMinutes(minutes))return toast('请检查实际分钟和速度。');practiceSaving=true;const record={id:sessionId,date:today(),trackId:'guitar',subject:'曲目练习',minutes,note:String(f.get('note')).trim(),practice:{kind:'guitar',songId:song.id,segmentId:segment?.id||'',title:song.title,segmentTitle:segment?.title||'全曲',bpm,clean:f.get('clean')==='on'}};upsertPracticeSession(record);if(segment&&record.practice.clean)segment.bestBpm=Math.max(segment.bestBpm||0,bpm);try{if(await save()){resetPracticeTimer();closeModal();render()}}finally{practiceSaving=false}}}
function upsertPracticeSession(record){const i=db.sessions.findIndex(s=>s.id===record.id);if(i>=0)db.sessions[i]=record;else db.sessions.push(record)}
function practiceAudioMime(audio){if(audio.type?.startsWith('audio/'))return audio.type;const ext=(audio.name||'').split('.').pop().toLowerCase();return ({mp3:'audio/mpeg',m4a:'audio/mp4',wav:'audio/wav',ogg:'audio/ogg',webm:'audio/webm'})[ext]||'audio/webm'}
function validBpm(n){return Number.isInteger(n)&&n>=30&&n<=240}
function validPracticeMinutes(n){return Number.isInteger(n)&&n>=1&&n<=720}
function practiceElapsed(){return Math.floor((practiceTimerElapsed+(practiceTimer?performance.now()-practiceTimerStarted:0))/1000)}
function updatePracticeClock(){const clock=$('#practiceClock');if(clock)clock.textContent=practiceClock(practiceElapsed());const button=$('#practiceTimerToggle');if(button)button.textContent=practiceTimer?'暂停计时':'开始计时'}
function togglePracticeTimer(){if(practiceTimer)stopPracticeTimer();else{practiceTimerStarted=performance.now();practiceTimer=setInterval(updatePracticeClock,250)}updatePracticeClock()}
function stopPracticeTimer(){if(practiceTimer){practiceTimerElapsed+=performance.now()-practiceTimerStarted;clearInterval(practiceTimer);practiceTimer=null}updatePracticeClock()}
function resetPracticeTimer(){stopPracticeTimer();practiceTimerElapsed=0;updatePracticeClock()}
function setMetronome(key,value){const next={...db.practice.metronome,[key]:Number(value)};if(!validMetronome(next)){toast('请检查节拍器设置。');render();return}stopMetronome();db.practice.metronome=next;save();render()}
function validMetronome(m){return m&&validBpm(m.bpm)&&Number.isInteger(m.beats)&&m.beats>=1&&m.beats<=8&&[1,2,3,4].includes(m.subdivision)&&Number.isFinite(m.volume)&&m.volume>=0&&m.volume<=0.7}
async function toggleMetronome(){if(metro.running){stopMetronome();render();return}const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){metro.error='当前浏览器不支持节拍播放。';render();return}const generation=++metro.generation;metro.error='';try{const ctx=new Audio();metro.ctx=ctx;await ctx.resume();if(generation!==metro.generation){ctx.close().catch(()=>{});return}if(ctx.state!=='running')throw Error('未能开启声音');metro.running=true;metro.next=ctx.currentTime+0.06;metro.tick=0;metroSchedule();metro.interval=setInterval(metroSchedule,25);render()}catch(error){stopMetronome();metro.error='无法播放节拍，请检查浏览器声音权限后重试。';render()}}
function metroSchedule(){if(!metro.running||!metro.ctx)return;const ctx=metro.ctx,m=db.practice.metronome,step=60/m.bpm/m.subdivision;let count=0;if(metro.next<ctx.currentTime-0.1)metro.next=ctx.currentTime+0.03;while(metro.next<ctx.currentTime+0.1&&count++<12){const tick=metro.tick++,beat=Math.floor(tick/m.subdivision)%m.beats,isMain=tick%m.subdivision===0,osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=isMain?(beat===0?1200:850):600;gain.gain.setValueAtTime(0.0001,metro.next);gain.gain.exponentialRampToValueAtTime(Math.max(0.0001,m.volume*(isMain?1:0.38)),metro.next+0.002);gain.gain.exponentialRampToValueAtTime(0.0001,metro.next+0.035);osc.connect(gain);gain.connect(ctx.destination);metro.nodes.add(osc);osc.onended=()=>{metro.nodes.delete(osc);osc.disconnect();gain.disconnect()};osc.start(metro.next);osc.stop(metro.next+0.04);if(isMain){const gen=metro.generation;const timer=setTimeout(()=>{metro.timeouts.delete(timer);if(gen===metro.generation&&metro.running){metro.beat=beat;updateMetronomeBeat(beat)}},Math.max(0,(metro.next-ctx.currentTime)*1000));metro.timeouts.add(timer)}metro.next+=step}}
function updateMetronomeBeat(beat){document.querySelectorAll('#metroBeats i').forEach((node,i)=>node.classList.toggle('on',metro.running&&i===beat))}
function stopMetronome(){metro.generation++;metro.running=false;clearInterval(metro.interval);metro.interval=null;for(const t of metro.timeouts)clearTimeout(t);metro.timeouts.clear();for(const node of metro.nodes){try{node.stop()}catch(_){}try{node.disconnect()}catch(_){}}metro.nodes.clear();const ctx=metro.ctx;metro.ctx=null;if(ctx)ctx.close().catch(()=>{});updateMetronomeBeat(-1);const button=$('#metroToggle');if(button)button.textContent='开始节拍';const state=$('#metroState');if(state)state.textContent='已停止'}
function englishPracticeView(){const p=practicePrompt(),draft=db.practice.drafts[p?.id]||{};return `<div class="pagehead"><div><h1>口语练习</h1></div><button class="primary" onclick="speakingPromptForm()">＋ 自建练习题</button></div>${!p?`<section class="card"><h2>先选一个题目</h2><p class="muted">这些是练习提示，不是官方雅思题库。</p><div class="speaking-starters">${speakingStarters.map((s,i)=>`<button onclick="useSpeakingStarter(${i})"><span class="tag">${esc(s.type)}</span><b>${esc(s.title)}</b><small>${s.seconds} 秒作答</small></button>`).join('')}</div></section>`:`<div class="practice-layout"><section class="card"><div class="practice-select-row"><label>练习题<select aria-label="口语练习题" onchange="selectPracticePrompt(this.value)">${db.practice.prompts.filter(x=>!x.archived).map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><button onclick="speakingPromptForm('${p.id}')">编辑</button></div><span class="tag">${esc(p.type)}</span><h2 class="speaking-question">${esc(p.title)}</h2><p class="speaking-prompt">${esc(p.prompt)}</p><p class="muted practice-caption">建议作答 ${p.seconds} 秒。先说一遍，再回听或整理文字。</p><div class="actions"><b class="practice-clock" id="practiceClock">${practiceClock(practiceElapsed())}</b><button id="practiceTimerToggle" onclick="togglePracticeTimer()">${practiceTimer?'暂停计时':'开始计时'}</button></div><div class="practice-recorder"><div class="actions"><button class="${capture.state==='recording'?'recording':'primary'}" onclick="${capture.state==='recording'?'stopSpeakingRecording()':'startSpeakingRecording()'}" ${['requesting','stopping'].includes(capture.state)?'disabled':''}>${capture.state==='recording'?'■ 停止录音':capture.state==='requesting'?'等待麦克风…':capture.state==='stopping'?'正在整理录音…':'● 开始录音'}</button><span id="speakingRecordingClock" class="muted">${capture.state==='recording'?practiceClock((performance.now()-capture.started)/1000):''}</span>${capture.blob?'<button onclick="discardSpeakingRecording()">丢弃录音</button>':''}</div>${capture.url?`<audio controls preload="metadata" src="${esc(capture.url)}" aria-label="本次录音回听"></audio>`:''}${capture.error?`<p class="practice-error">${esc(capture.error)}</p>`:''}<small class="muted">录音仅保存在本机。也可在保存时选择已有音频。</small></div></section><section class="card"><h2>整理这一次的表达</h2><label>作答文字<textarea id="speakingText" aria-label="口语作答文字" maxlength="6000" placeholder="写下刚才说的内容，或先列出想表达的要点。">${esc(draft.text||'')}</textarea></label><label>回听后的发现<textarea id="speakingReview" aria-label="回听后的发现" maxlength="2000" placeholder="例如：重复用了很多 very，过去时不稳定。">${esc(draft.review||'')}</textarea></label><label>下次只改进一件事<input id="speakingNext" aria-label="下次改进" maxlength="240" value="${esc(draft.nextFocus||'')}"></label><div class="actions"><button class="primary" onclick="speakingLogForm()" ${['recording','requesting','stopping'].includes(capture.state)?'disabled':''}>保存本次练习</button></div></section></div>`}<details class="card"><summary>更多练习提示 / 已归档</summary><div class="speaking-starters">${speakingStarters.map((s,i)=>`<button onclick="useSpeakingStarter(${i})">${esc(s.title)}</button>`).join('')}</div>${db.practice.prompts.filter(x=>x.archived).map(x=>`<div class="row"><b>${esc(x.title)}</b><button onclick="restorePracticeItem('prompt','${x.id}')">恢复</button></div>`).join('')}</details>${practiceHistory('english',p?.id)}`}
function useSpeakingStarter(i){const s=speakingStarters[i];if(!s)return;if(!canChangeSpeakingPrompt())return;const existing=db.practice.prompts.find(p=>p.starter===i);if(existing){existing.archived=false;practicePromptId=existing.id}else{if(db.practice.prompts.length>=300)return toast('练习题最多300个。');const p={...s,id:uid(),starter:i,archived:false};db.practice.prompts.push(p);practicePromptId=p.id}resetPracticeTimer();save();render()}
function canChangeSpeakingPrompt(){if(['recording','ready','requesting','stopping'].includes(capture.state)){if(!confirm('切换题目会丢弃尚未保存的录音，继续？'))return false;discardSpeakingRecording(true)}flushPracticeDraft();return true}
function selectPracticePrompt(id){if(!canChangeSpeakingPrompt()){render();return}practicePromptId=id;resetPracticeTimer();render()}
function speakingPromptForm(id){const p=db.practice.prompts.find(x=>x.id===id)||{title:'',type:'日常口语',prompt:'',seconds:90};show(`<h2>${id?'编辑':'自建'}练习题</h2><form id="speakingPromptForm"><label>题目名称<input name="title" required maxlength="120" value="${esc(p.title)}"></label><label>类型<select name="type">${opts(speakingTypes,p.type)}</select></label><label>练习提示<textarea name="prompt" maxlength="3000" required placeholder="输入一个想练的话题、英文问题或跟读文本。">${esc(p.prompt)}</textarea></label><label>建议作答秒数<input name="seconds" type="number" min="15" max="600" value="${p.seconds}" required></label><div class="actions"><button class="primary">保存题目</button>${id?`<button type="button" onclick="archivePracticeItem('prompt','${id}')">归档</button>`:''}</div></form>`);$('#speakingPromptForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),title=String(f.get('title')).trim(),prompt=String(f.get('prompt')).trim(),seconds=+f.get('seconds');if(!title||!prompt||!Number.isInteger(seconds)||seconds<15||seconds>600)return toast('请填写题目、提示和15～600秒的时长。');if(!canChangeSpeakingPrompt())return;const values={title,prompt,type:f.get('type'),seconds};if(id)Object.assign(p,values);else{if(db.practice.prompts.length>=300)return toast('练习题最多300个。');const item={id:uid(),...values,archived:false};db.practice.prompts.push(item);practicePromptId=item.id}if(await save()){closeModal();render()}}}
function storeSpeakingDraft(){const p=practicePrompt();if(!p)return;db.practice.drafts[p.id]={text:$('#speakingText')?.value||'',review:$('#speakingReview')?.value||'',nextFocus:$('#speakingNext')?.value||''};clearTimeout(practiceDraftTimer);practiceDraftTimer=setTimeout(()=>{practiceDraftTimer=null;save()},350)}
function flushPracticeDraft(){if(practiceDraftTimer){clearTimeout(practiceDraftTimer);practiceDraftTimer=null;save()}}
document.addEventListener('input',e=>{if(['speakingText','speakingReview','speakingNext'].includes(e.target.id))storeSpeakingDraft()});
async function startSpeakingRecording(){const p=practicePrompt();if(!p||['recording','requesting','stopping'].includes(capture.state))return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){capture.error='当前浏览器不能直接录音，可在保存练习时上传音频。';render();return}if(capture.blob&&!confirm('重新录制会丢弃这一段未保存录音，继续？'))return;discardSpeakingRecording(true);const token=++capture.generation;capture.state='requesting';capture.promptId=p.id;render();try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(token!==capture.generation){stream.getTracks().forEach(t=>t.stop());return}capture.stream=stream;const options=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(m=>MediaRecorder.isTypeSupported(m));const recorder=options?new MediaRecorder(stream,{mimeType:options}):new MediaRecorder(stream);capture.recorder=recorder;capture.chunks=[];let bytes=0;recorder.ondataavailable=e=>{if(token!==capture.generation||!e.data.size)return;bytes+=e.data.size;if(bytes>50*1024*1024){capture.error='录音已达到50MB，已停止。';stopSpeakingRecording();return}capture.chunks.push(e.data)};recorder.onerror=()=>{if(token!==capture.generation)return;capture.error='录音中断，请检查麦克风，或上传已有音频。';stopSpeakingRecording()};recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());if(token!==capture.generation)return;clearInterval(capture.timer);capture.timer=null;capture.stream=null;capture.recorder=null;capture.seconds=Math.max(0,Math.round((performance.now()-capture.started)/1000));capture.blob=new Blob(capture.chunks,{type:recorder.mimeType||'audio/webm'});capture.chunks=[];if(capture.blob.size){capture.url=URL.createObjectURL(capture.blob);capture.state='ready'}else{capture.state='error';capture.blob=null;capture.error='没有录到声音文件，请重新录制或上传音频。'}if(page==='englishPractice')render()};capture.started=performance.now();capture.state='recording';recorder.start(1000);capture.timer=setInterval(()=>{const elapsed=(performance.now()-capture.started)/1000;const clock=$('#speakingRecordingClock');if(clock)clock.textContent=practiceClock(elapsed);if(elapsed>=600)stopSpeakingRecording()},250);render()}catch(error){if(token!==capture.generation)return;capture.stream?.getTracks().forEach(t=>t.stop());capture.stream=null;capture.state='error';capture.error=error.name==='NotAllowedError'?'没有获得麦克风权限。你仍可上传已有音频。':'无法开启麦克风，请检查设备或上传已有音频。';render()}}
function stopSpeakingRecording(){if(capture.state!=='recording')return;capture.state='stopping';clearInterval(capture.timer);capture.timer=null;try{capture.recorder.stop()}catch(_){capture.stream?.getTracks().forEach(t=>t.stop());capture.state='error';capture.error='录音未完成，请重试。'}if(page==='englishPractice')render()}
function discardSpeakingRecording(silent=false){if(!silent&&!confirm('丢弃尚未保存的这段录音？'))return;capture.generation++;clearInterval(capture.timer);if(capture.recorder&&capture.recorder.state!=='inactive'){try{capture.recorder.stop()}catch(_){}}capture.stream?.getTracks().forEach(t=>t.stop());if(capture.url)URL.revokeObjectURL(capture.url);capture={generation:capture.generation,state:'idle',stream:null,recorder:null,chunks:[],blob:null,url:'',started:0,seconds:0,promptId:null,error:'',timer:null};if(!silent&&page==='englishPractice')render()}
function speakingLogForm(){const prompt=practicePrompt();if(!prompt||['recording','requesting','stopping'].includes(capture.state))return;flushPracticeDraft();stopPracticeTimer();const draft={...(db.practice.drafts[prompt.id]||{})},sessionId=uid(),blob=capture.promptId===prompt.id?capture.blob:null;let stagedMaterial=null;const seconds=Math.max(practiceElapsed(),capture.seconds);show(`<h2>保存本次口语练习</h2><form id="speakingLogForm"><p>${esc(prompt.title)}</p><label>实际练习分钟<input name="minutes" type="number" min="1" max="720" value="${seconds?Math.max(1,Math.round(seconds/60)):5}" required></label>${blob?'<p>包含刚才的录音。</p>':'<label>附上已有音频（可选，最多50MB）<input name="audio" type="file" accept="audio/*,.m4a,.mp3,.wav,.webm,.ogg"></label>'}<p id="speakingSaveError" class="practice-error" role="status"></p><button class="primary" id="speakingSaveButton">保存练习</button></form>`);$('#speakingLogForm').onsubmit=async e=>{e.preventDefault();if(practiceSaving)return;const f=new FormData(e.target),minutes=+f.get('minutes');if(!validPracticeMinutes(minutes))return;practiceSaving=true;$('#speakingSaveButton').disabled=true;try{const file=f.get('audio'),audio=blob||(file?.size?file:null);if(audio&&!stagedMaterial){if(audio.size>50*1024*1024)throw Error('音频超过50MB，请截短后再保存。');if(audio.type&&!audio.type.startsWith('audio/')&&!/\.(mp3|m4a|wav|webm|ogg)$/i.test(audio.name||''))throw Error('请选择音频文件。');const mime=practiceAudioMime(audio),fileId=uid(),extension=mime.includes('mp4')?'m4a':mime.includes('wav')?'wav':mime.includes('mpeg')?'mp3':mime.includes('ogg')?'ogg':'webm';await fileOp('put',fileId,audio);stagedMaterial={id:uid(),trackId:'english',title:prompt.title+' · '+today()+' 录音',subject:'口语',tags:'练习录音',current:0,total:0,unit:'次',status:'已完成',created:today(),fileId,fileName:audio.name||'speaking-'+today()+'.'+extension,size:audio.size,mime,note:'关联口语练习记录'};db.materials.push(stagedMaterial)}const record={id:sessionId,date:today(),trackId:'english',subject:prompt.type.includes('雅思')?'雅思':'口语',minutes,note:[draft.review,draft.nextFocus?'下次：'+draft.nextFocus:''].filter(Boolean).join('\n').slice(0,2000),practice:{kind:'english',promptId:prompt.id,title:prompt.title,prompt:prompt.prompt,type:prompt.type,text:draft.text||'',review:draft.review||'',nextFocus:draft.nextFocus||'',audioMaterialId:stagedMaterial?.id||''}};upsertPracticeSession(record);if(!await save())throw Error('尚未写入本地。请保留页面并重试，或导出备份。');delete db.practice.drafts[prompt.id];await save();discardSpeakingRecording(true);resetPracticeTimer();closeModal();render()}catch(error){$('#speakingSaveError').textContent=error.message}finally{practiceSaving=false;const b=$('#speakingSaveButton');if(b)b.disabled=false}}}
function askSpeakingAI(){const p=practicePrompt(),d=db.practice.drafts[p?.id]||{};if(!p)return;if(!d.text?.trim())return toast('先写下你的作答文字，再带入问答。');if(['requesting','recording','stopping'].includes(capture.state)||capture.blob)return toast('请先保存本次录音，再带文字问 AI。');flushPracticeDraft();personalTrackId='english';db.personal.activeTrack='english';save();setTeacherDraftForProject('english',`我在练习${p.type}。\n题目：${p.prompt.slice(0,800)}\n我的作答：\n${d.text.slice(0,6000)}\n${d.review?'我的发现：'+d.review.slice(0,300)+'\n':''}请先指出最影响表达的2～3个问题，再给一版保留我原意的自然表达。只评估文字，不对未提供的音频评价发音，也不要虚构雅思分数。`);teacherTab='chat';go('teacher')}
function askSpeakingRecordAI(id){const s=db.sessions.find(s=>s.id===id),p=s?.practice;if(!p||p.kind!=='english'||!p.text?.trim())return;if(!preparePracticeLeave())return;personalTrackId='english';db.personal.activeTrack='english';save();setTeacherDraftForProject('english',`我在练习${p.type}。\n题目：${p.prompt.slice(0,800)}\n我的作答：\n${p.text.slice(0,6000)}\n${p.review?'我的发现：'+p.review.slice(0,300)+'\n':''}请指出最影响表达的2～3个问题，再给一版保留原意的自然表达。只评估文字，不评价未提供的音频和发音，不虚构雅思分数。`);teacherTab='chat';go('teacher')}
function practiceHistory(kind,targetId){const rows=practiceSessions(kind).filter(s=>!targetId||(kind==='guitar'?s.practice.songId===targetId:s.practice.promptId===targetId)).slice(-12).reverse();return `<section class="card practice-history"><h2>最近练习</h2>${rows.length?rows.map(s=>`<article class="practice-history-entry"><div class="actions" style="justify-content:space-between"><b>${esc(s.practice.title)}${kind==='guitar'?' · '+esc(s.practice.segmentTitle):''}</b><small class="muted">${esc(s.date)} · ${s.minutes} 分钟</small></div>${kind==='guitar'?`<span class="tag">${s.practice.bpm} BPM${s.practice.clean?' · 已确认顺畅':''}</span>`:''}${s.note?`<p class="practice-note">${esc(s.note)}</p>`:''}${kind==='english'&&s.practice.text?`<details><summary>查看作答与题目</summary><p class="speaking-prompt">${esc(s.practice.prompt)}</p><p class="practice-note">${esc(s.practice.text)}</p></details>`:''}<div class="actions"><button onclick="sessionForm(${db.sessions.indexOf(s)})">修改时间 / 笔记</button>${s.practice.audioMaterialId&&db.materials.some(m=>m.id===s.practice.audioMaterialId)?`<button onclick="playPracticeAudio('${s.practice.audioMaterialId}','audio-${s.id}')">回听录音</button>`:''}</div>${s.practice.audioMaterialId?`<div id="audio-${s.id}" class="practice-audio-slot"></div>`:''}</article>`).join(''):'<p class="empty">完成一次练习后，记录会出现在这里。</p>'}</section>`}
async function playPracticeAudio(materialId,slotId){const material=db.materials.find(m=>m.id===materialId),slot=document.getElementById(slotId);if(!material||!slot)return;try{let url=practiceAudioURLs.get(materialId);if(!url){const raw=await fileOp('get',material.fileId);url=URL.createObjectURL(new Blob([raw],{type:material.mime||'audio/webm'}));practiceAudioURLs.set(materialId,url)}if(!slot.isConnected)return;slot.replaceChildren();const audio=document.createElement('audio');audio.controls=true;audio.preload='metadata';audio.src=url;audio.setAttribute('aria-label',material.title);slot.append(audio);audio.play().catch(()=>{})}catch(error){toast('录音未能读取：'+error.message)}}
async function archivePracticeItem(kind,id){const items=kind==='song'?db.practice.songs:db.practice.prompts,item=items.find(x=>x.id===id);if(!item||!confirm('归档后可在页面下方恢复，练习记录仍保留。继续？'))return;if(kind==='prompt'&&!canChangeSpeakingPrompt())return;item.archived=true;if(kind==='song'){practiceSongId=null;practiceSegmentId=null;stopMetronome()}else practicePromptId=null;if(await save()){closeModal();render()}}
async function restorePracticeItem(kind,id){const item=(kind==='song'?db.practice.songs:db.practice.prompts).find(x=>x.id===id);if(item){item.archived=false;if(await save())render()}}
const validateBeforePractice=validData;
validData=function(d){if(!validateBeforePractice(d))return false;const id=x=>typeof x==='string'&&/^[a-zA-Z0-9-]{1,100}$/.test(x),text=(x,n)=>typeof x==='string'&&x.length<=n,array=(x,n)=>Array.isArray(x)&&x.length<=n;try{if(d.practice!==undefined){const p=d.practice;if(!p||p.version!==1||!array(p.songs,300)||!array(p.prompts,300)||!p.drafts||typeof p.drafts!=='object'||Array.isArray(p.drafts)||Object.keys(p.drafts).length>300||!validMetronome(p.metronome))return false;if(!p.songs.every(s=>s&&id(s.id)&&text(s.title,120)&&text(s.artist,100)&&(s.materialId===''||id(s.materialId))&&['练习中','能完整演奏','暂放'].includes(s.status)&&typeof s.archived==='boolean'&&text(s.note,2000)&&array(s.segments,100)&&new Set(s.segments.map(x=>x.id)).size===s.segments.length&&s.segments.every(x=>x&&id(x.id)&&text(x.title,100)&&text(x.range,120)&&validBpm(x.startBpm)&&validBpm(x.targetBpm)&&x.startBpm<=x.targetBpm&&(x.bestBpm===0||validBpm(x.bestBpm)))))return false;if(!p.prompts.every(p=>p&&id(p.id)&&text(p.title,120)&&text(p.prompt,3000)&&speakingTypes.includes(p.type)&&typeof p.archived==='boolean'&&Number.isInteger(p.seconds)&&p.seconds>=15&&p.seconds<=600))return false;if(new Set(p.songs.map(x=>x.id)).size!==p.songs.length||new Set(p.prompts.map(x=>x.id)).size!==p.prompts.length)return false;if(!Object.entries(p.drafts).every(([k,v])=>id(k)&&v&&text(v.text,6000)&&text(v.review,2000)&&text(v.nextFocus,240)))return false}return d.sessions.every(s=>{const p=s.practice;if(p===undefined)return true;if(!p||!id(s.id)||!text(p.title,120))return false;return p.kind==='guitar'?id(p.songId)&&(p.segmentId===''||id(p.segmentId))&&text(p.segmentTitle,100)&&validBpm(p.bpm)&&typeof p.clean==='boolean':p.kind==='english'?id(p.promptId)&&text(p.prompt,3000)&&speakingTypes.includes(p.type)&&text(p.text,6000)&&text(p.review,2000)&&text(p.nextFocus,240)&&(p.audioMaterialId===''||id(p.audioMaterialId)):false})}catch(_){return false}};
const importBeforePractice=importData;
importData=async function(file){stopMetronome();stopPracticeTimer();if(capture.state!=='idle'&&capture.state!=='error'){if(!confirm('导入会丢弃尚未保存的录音，继续？'))return;discardSpeakingRecording(true)}flushPracticeDraft();await importBeforePractice(file);normalizePractice();practiceSongId=null;practiceSegmentId=null;practicePromptId=null;resetPracticeTimer();releasePracticeAudio();render()};
window.addEventListener('beforeunload',event=>{flushPracticeDraft();if(['requesting','recording','stopping','ready'].includes(capture.state)){event.preventDefault();event.returnValue=''}});
window.addEventListener('pagehide',()=>{stopMetronome();discardSpeakingRecording(true);releasePracticeAudio()});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&metro.running)stopMetronome()});

// Short, original Chinese lessons; references are optional further reading.
const guitarBasicsLessons = [
 {title:'先认清弦和品',goal:'找到别人说的“几弦几品”。',
  points:['最细的是1弦，最粗的是6弦。标准调弦从6弦到1弦是 E A D G B E；两根E相差两个八度。','0品就是空弦，不按左手。1品是琴枕后第一个格子，手指按在格内、靠近右侧品丝，不压在品丝上。','音名是 C D E F G A B。先记弦的音名，再理解它们在不同调里的唱名。'],
  example:'“2弦1品”＝第二细的弦，按第一个格子，弹出来是C。不是弹第1弦两次。',
  practice:'调好音，从6弦到1弦慢弹并念 E A D G B E，再找出2弦1品的C。',tool:'fretboard',source:'https://www.fender.com/articles/chords/how-to-read-a-chord-chart',sourceName:'Fender · 弦序与指板图'},
 {title:'六线谱、简谱怎么看',goal:'分清“按哪里”和“唱什么”。',
  points:['六线谱从上到下是1至6弦，上面最细、下面最粗；从左往右读。数字表示品位，不是手指，也不是简谱音级。','数字0＝空弦；上下对齐的数字通常一起弹。只写数字的纯六线谱不一定能交代节奏，还要看符干、节奏标记或配套示范。','简谱1～7通常表示调内音级；1=C时，1对应C，1=D时对应D。0表示休止，音符上下的点表示八度。五线谱主要用音符位置表示音高、形状表示时值。'],
  example:'下面是原创C大调练习，每个音先弹一拍。开头依次是5弦3品、4弦0品、4弦2品，音名C、D、E。',
  practice:'按下面的六线谱慢弹8个音，边弹边念 C D E F G A B C。',tool:'tab',source:'https://www.fender.com/articles/techniques/how-to-read-tabs',sourceName:'Fender · 六线谱'},
 {title:'先把节奏弹稳',goal:'知道拍号、速度和音符时值分别说什么。',
  points:['4/4表示每小节4拍、四分音符作一拍；3/4每小节3拍。BPM是每分钟的拍数，这里的练习都让节拍器每响一次对应一拍。','在4/4里：四分音符1拍，二分音符2拍，全音符4拍，八分音符半拍。休止也要数拍，不是暂停计时。','先一拍一下弹空弦，再一拍两下，口数“1 和 2 和 3 和 4 和”。慢而均匀，比突然快起来更重要。'],
  example:'60 BPM：一拍约1秒。四分音符弹4下占一小节；八分音符弹8下也占一小节。',
  practice:'节拍器设60 BPM、每小节4拍。先一拍弹1下，稳住后改成一拍2下，各练1分钟。',tool:'rhythm',source:'https://musictheory.pugetsound.edu/mt21c/TimeSignature.html',sourceName:'普吉特海湾大学 · 拍号'},
 {title:'半音、全音与音阶',goal:'理解为什么有的音隔一品，有的隔两品。',
  points:['同一根弦上，每往琴桥方向一品升高一个半音；两品是一个全音。升号♯升半音，降号♭降半音。','自然音中 E—F、B—C只差半音；C—D、D—E、F—G、G—A、A—B差全音。C♯和D♭在常用十二平均律中同音，名称看语境。','大调音阶的间隔是“全 全 半 全 全 全 半”。从C出发得到C D E F G A B C；从G出发得到G A B C D E F♯ G。'],
  example:'1弦空弦是E，1品F，2品F♯，3品G。不是每个字母之间都有一个升号音。',
  practice:'在1弦依次弹0、1、3、5品，念 E F G A；再解释E到F为什么只移动一品。',tool:'fretboard',source:'https://musictheory.pugetsound.edu/mt21c/TheMajorScale.html',sourceName:'普吉特海湾大学 · 大调音阶'},
 {title:'和弦是什么、图怎么看',goal:'理解和弦名字与按法的关系。',
  points:['先学三和弦：三个不同音按三度关系组合。C大三和弦的音是C E G；Am小三和弦是A C E。吉他可以重复某些音，所以按5根弦不等于5种音。','大三和弦从根音到三音4个半音、三音到五音3个；小三和弦反过来是3＋4。Am里的m表示“小”，不是“把A弹轻一点”。','下图左到右是6至1弦，上方是琴枕。×不弹，○弹空弦，圆点内1/2/3/4分别是左手食指/中指/无名指/小指；圆点所在格子才是品位。'],
  example:'C和弦常用按法 x32010：6弦不弹、5弦3品、4弦2品、3弦空弦、2弦1品、1弦空弦。',
  practice:'先选Em，再选Am、C。按好后逐根拨，听是否每根该响的弦都清楚，不急着换和弦。',tool:'chords',source:'https://musictheory.pugetsound.edu/mt21c/TriadsIntroduction.html',sourceName:'普吉特海湾大学 · 三和弦'},
 {title:'“什么调”和“几级和弦”',goal:'分清C调、C和弦与简谱的1。',
  points:['调是整段音乐围绕的主音和音阶体系；和弦是某个时刻使用的一组音。C大调不是整首歌只弹C和弦，也不能只看第一个和弦判断调。','在C大调中，音级1～7对应C D E F G A B。由这些音建立的三和弦依次是C、Dm、Em、F、G、Am、Bdim；大调记 I ii iii IV V vi vii°。','常说的“1—5—6—4”，在C大调常指C—G—Am—F；在G大调则是G—D—Em—C。这里讲的是和弦级数，不是六线谱的品数。'],
  example:'看到1=C，是简谱主音的音高；看到C，是和弦符号时表示C大和弦。它们用同一个字母，说的对象不同。',
  practice:'先在纸上写出C大调的1、4、5、6级和弦：C、F、G、Am，再对照一份熟悉的歌谱。',tool:'degrees',source:'https://musictheory.pugetsound.edu/mt21c/DiatonicChordsInMajor.html',sourceName:'普吉特海湾大学 · 大调调内和弦'},
 {title:'变调夹与实际听到的调',goal:'看懂“选调C、Capo 2”这种标注。',
  points:['变调夹把它所在的位置当成新的空弦起点。夹高一品，按同一套指型，实际音高升一个半音。','C指型配Capo 2，实际响的是D和弦；Am指型配Capo 2，实际响的是Bm。和弦性质不变，根音整体升高。','六线谱在使用变调夹时通常从夹子重新计品，但要先看该谱的说明。选调/指型与原调/实际调可能不同，不能只看字母猜。'],
  example:'谱写“选调C，Capo 2”：若整段按C大调指型弹，实际响D大调。下面只换算单个和弦，不替整首歌判断调。',
  practice:'不夹时弹C，再夹2品按同样指型弹C，听整体变高；夹好后检查调音。',tool:'capo',source:'https://hub.yamaha.com/guitars/g-how-to/the-art-of-using-a-capo/',sourceName:'Yamaha · 变调夹'},
 {title:'把会弹的一首歌看懂',goal:'把学到的基础用回真实的歌。',
  points:['拿一首你已经会弹的歌，先找拍号、速度、调或选调、Capo位置。缺失的先标“待确认”，不要只凭第一个和弦下结论。','挑4小节，圈出和弦变化，写清每个和弦持续几拍。分清旋律、和弦名、左手指型与右手节奏。','先用原来会的按法慢弹，再解释：这一下弹哪根弦？是什么音？当前是什么和弦？实际响什么调？一次只解决一个不懂的地方。'],
  example:'原创练习：1=C，4/4，60 BPM，无变调夹。| C | G | Am | C |，每小节一个和弦、每拍向下扫一次。',
  practice:'先用60 BPM弹完这4小节；再拿自己熟悉的一首歌，标出调、拍号、变调夹与4小节和弦。',tool:'application',source:'https://www.fender.com/articles/techniques/how-to-read-tabs',sourceName:'Fender · 读谱参考'}
];
const guitarBasicChords = {
 C:{frets:[null,3,2,0,1,0],fingers:[0,3,2,0,1,0],tones:'C E G'},
 Am:{frets:[null,0,2,2,1,0],fingers:[0,0,2,3,1,0],tones:'A C E'},
 Em:{frets:[0,2,2,0,0,0],fingers:[0,2,3,0,0,0],tones:'E G B'},
 G:{frets:[3,2,0,0,0,3],fingers:[2,1,0,0,0,3],tones:'G B D'},
 D:{frets:[null,null,0,2,3,2],fingers:[0,0,0,1,3,2],tones:'D F♯ A'}
};
let guitarBasicsIndex=0,guitarBasicChord='Em',guitarBasicCapo=2,guitarBasicShape='C';
const guitarPitchNames=['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'];
const guitarOpenMidi=[40,45,50,55,59,64];
function guitarFretNote(string,fret){const midi=guitarOpenMidi[6-string]+fret;return guitarPitchNames[midi%12]+(Math.floor(midi/12)-1)}
function guitarCapoChord(shape,fret){const roots={C:0,Am:9,Em:4,G:7,D:2};return guitarPitchNames[(roots[shape]+fret)%12]+(shape.endsWith('m')?'m':'')}
function guitarChordDiagram(name,collection=guitarBasicChords){
 const chord=collection[name],barres=chord.barres||[];
 const positive=chord.frets.filter(fret=>fret>0),start=Math.max(...positive)>4?Math.min(...positive):1;
 const label=chord.frets.map((fret,i)=>`${6-i}弦${fret===null?'不弹':fret===0?'空弦':fret+'品'}`).join('，');
 const y=fret=>52+(fret-start)*34;
 return `<svg viewBox="0 0 180 205" role="img" aria-label="${name}和弦：${label}${barres.length?'；长条表示同一根手指横按':''}">
 <title>${name}和弦指法图</title><g fill="none" stroke="currentColor" opacity=".55">
 ${Array.from({length:6},(_,i)=>`<path d="M${30+i*24} 35V171"/>`).join('')}
 ${Array.from({length:5},(_,i)=>`<path d="M30 ${35+i*34}H150" stroke-width="${!i&&start===1?4:1}"/>`).join('')}</g>
 ${start>1?`<text x="7" y="57" font-size="11" fill="currentColor">${start}品</text>`:''}
 ${barres.map(([fret,from,to,finger])=>`<rect x="${20+(6-from)*24}" y="${y(fret)-10}" width="${(from-to)*24+20}" height="20" rx="10" fill="var(--green)"/><text x="${30+(6-(from+to)/2)*24}" y="${y(fret)+4}" text-anchor="middle" fill="white" font-size="12">${finger}</text>`).join('')}
 ${chord.frets.map((fret,i)=>`<text x="${30+i*24}" y="23" text-anchor="middle" fill="currentColor" font-size="16">${fret===null?'×':fret===0?'○':''}</text>
 ${fret>0&&!barres.some(([f,from,to,finger])=>f===fret&&6-i<=from&&6-i>=to&&finger===chord.fingers[i])?`<circle cx="${30+i*24}" cy="${y(fret)}" r="10" fill="var(--green)"/><text x="${30+i*24}" y="${y(fret)+4}" text-anchor="middle" fill="white" font-size="12">${chord.fingers[i]}</text>`:''}
 <text x="${30+i*24}" y="193" text-anchor="middle" fill="currentColor" font-size="11">${6-i}弦</text>`).join('')}</svg>`;
}
function guitarBasicsTool(kind){
 if(kind==='fretboard')return `<div class="guitar-fretboard" role="group" aria-label="标准调弦指板，0至5品"><div class="guitar-fret-row"><span></span>${Array.from({length:6},(_,f)=>`<span>${f===0?'空弦':f+'品'}</span>`).join('')}</div>${[1,2,3,4,5,6].map(string=>`<div class="guitar-fret-row"><span>${string}弦</span>${Array.from({length:6},(_,fret)=>`<button type="button" aria-label="${string}弦${fret}品 ${guitarFretNote(string,fret)}" onclick="document.querySelector('#guitarNoteInfo').textContent='${string}弦${fret}品：${guitarFretNote(string,fret)}'">${guitarFretNote(string,fret).replace(/\d/,'')}</button>`).join('')}</div>`).join('')}<p id="guitarNoteInfo" role="status">点位置看音名；C4中的4是八度编号，不是品数。1弦在上，6弦在下。</p></div>`;
 if(kind==='tab'){
  const notes=[[5,3],[4,0],[4,2],[4,3],[3,0],[3,2],[2,0],[2,1]];
  const tab=[1,2,3,4,5,6].map((string,i)=>`${['e','B','G','D','A','E'][i]} |`+notes.map(([s,f])=>s===string?f+'-':'--').join('')+'|').join('\n');
  return `<pre class="guitar-tab" aria-label="C大调六线谱，依次弹C D E F G A B C">${tab}</pre><p class="muted">每列一个音，每个音1拍；本例时值由文字指定。上面的e是高音E弦。</p>`;
 }
 if(kind==='chords')return `<div class="actions">${Object.keys(guitarBasicChords).map(name=>`<button type="button" aria-pressed="${guitarBasicChord===name}" onclick="guitarBasicChord='${name}';render()">${name}</button>`).join('')}</div><button type="button" onclick="go('guitarChords')">打开常见和弦库</button><figure class="guitar-chord">${guitarChordDiagram(guitarBasicChord)}<figcaption><strong>${guitarBasicChord}</strong> · 组成音 ${guitarBasicChords[guitarBasicChord].tones}</figcaption></figure>`;
 if(kind==='capo')return `<div class="formgrid"><label>弹的指型<select aria-label="变调夹和弦指型" onchange="guitarBasicShape=this.value;render()">${Object.keys(guitarBasicChords).map(name=>`<option ${name===guitarBasicShape?'selected':''}>${name}</option>`).join('')}</select></label><label>变调夹位置<select aria-label="变调夹位置" onchange="guitarBasicCapo=Number(this.value);render()">${Array.from({length:8},(_,f)=>`<option value="${f}" ${f===guitarBasicCapo?'selected':''}>${f===0?'不夹':f+'品'}</option>`).join('')}</select></label></div><p class="guitar-capo-result" role="status">${guitarBasicShape} 指型 ＋ ${guitarBasicCapo} 品 → 实际响 <strong>${guitarCapoChord(guitarBasicShape,guitarBasicCapo)}</strong> 和弦</p>`;
 if(kind==='degrees')return '<p class="guitar-notation">C大调：I C · ii Dm · iii Em · IV F · V G · vi Am · vii° Bdim</p>';
 if(kind==='rhythm')return '<p class="guitar-notation">四分：1　2　3　4<br>八分：1 和 2 和 3 和 4 和</p>';
 return '<p class="guitar-notation">1=C　4/4　60 BPM　Capo 0<br>| C | G | Am | C |</p>';
}
function guitarBasicsView(){const lesson=guitarBasicsLessons[guitarBasicsIndex];return `<div class="pagehead"><div><h1>吉他基础</h1><p class="muted">会弹歌，从这里补乐理。每次一课，先读懂，再拿琴试。</p></div></div>
 <div class="guitar-basics-layout"><nav class="guitar-lessons" aria-label="吉他基础课程">${guitarBasicsLessons.map((item,index)=>`<button type="button" aria-current="${index===guitarBasicsIndex?'step':'false'}" onclick="selectGuitarBasics(${index})"><small>${String(index+1).padStart(2,'0')}</small>${item.title}</button>`).join('')}</nav>
 <article class="card guitar-lesson"><small class="muted">第 ${guitarBasicsIndex+1} / ${guitarBasicsLessons.length} 课</small><h2>${lesson.title}</h2><p class="guitar-lesson-goal">${lesson.goal}</p>
 ${lesson.points.map(text=>`<p>${text}</p>`).join('')}
 ${guitarBasicsTool(lesson.tool)}
 <div class="guitar-lesson-example"><strong>对照着看</strong><p>${lesson.example}</p></div>
 <div class="guitar-lesson-practice"><strong>拿琴练 5 分钟</strong><p>${lesson.practice}</p></div>
 <div class="actions"><button type="button" onclick="arrangeGuitarBasics()">安排这项练习</button><button type="button" onclick="openPractice('guitar')">打开节拍器</button></div>
 <details class="guitar-reference"><summary>参考资料（英文，可选）</summary><a href="${lesson.source}" target="_blank" rel="noopener noreferrer">${lesson.sourceName} ↗</a></details>
 <div class="actions guitar-lesson-pager">${guitarBasicsIndex?'<button type="button" onclick="selectGuitarBasics(guitarBasicsIndex-1)">上一课</button>':''}${guitarBasicsIndex<guitarBasicsLessons.length-1?'<button type="button" class="primary" onclick="selectGuitarBasics(guitarBasicsIndex+1)">下一课</button>':''}</div>
 </article></div>`}
function selectGuitarBasics(index){if(!Number.isInteger(index)||!guitarBasicsLessons[index])return;guitarBasicsIndex=index;render();$('#view').scrollIntoView?.({block:'start'})}
function arrangeGuitarBasics(){if(navigationProject!=='guitar')return;taskForm('guitar');const form=$('#personalTaskForm');if(!form?.elements)return;form.elements.title.value=guitarBasicsLessons[guitarBasicsIndex].practice;if([...form.elements.subject.options].some(option=>option.value==='乐理'))form.elements.subject.value='乐理';form.elements.minutes.value=5}


