const guitarMemoryChordMap=Object.fromEntries(guitarMemoryChordList.map(chord=>[chord.name,chord]));
let guitarChordMemoryGroup='先记',guitarChordMemoryQuery='',guitarChordMemoryHidden=false;
function guitarChordMemoryResults(){
 const query=guitarChordMemoryQuery.trim().replaceAll('♯','#').replaceAll('♭','b').toLowerCase();
 const matches=guitarMemoryChordList.filter(chord=>(guitarChordMemoryGroup==='全部'||chord.group===guitarChordMemoryGroup)&&
  (!query||(chord.name+' '+chord.kind+' '+chord.tones).replaceAll('♯','#').replaceAll('♭','b').toLowerCase().includes(query)));
 return matches.map(chord=>`<article class="card guitar-memory-card"><header><h2>${chord.name}</h2><span class="tag">${chord.kind}</span></header>
 <details ${guitarChordMemoryHidden?'':'open'}><summary>指法与组成音</summary>${guitarChordDiagram(chord.name,guitarMemoryChordMap)}
 <p class="guitar-memory-tones">组成音 · ${chord.tones}</p>
 <p class="guitar-memory-frets">6 → 1弦：${chord.frets.map(fret=>fret===null?'x':fret).join(' ')}</p>
 ${chord.note?`<p class="muted guitar-memory-note">${chord.note}</p>`:''}</details></article>`).join('')||'<section class="card empty">这一组里没有匹配的和弦，试试“全部”或换个名字。</section>';
}
function guitarChordsView(){return `<div class="pagehead"><div><h1>和弦速记</h1><p class="muted">${guitarMemoryChordList.length} 个常见和弦，每个先记一种实用按法。先背8个开放和弦，再逐步扩展。</p></div></div>
 <div class="card guitar-memory-toolbar"><div class="actions" aria-label="和弦学习分组">${['先记','扩展','横按','全部'].map(group=>`<button type="button" aria-pressed="${guitarChordMemoryGroup===group}" onclick="guitarChordMemoryGroup='${group}';render()">${group==='先记'?'先记8个':group==='扩展'?'常用扩展':group==='横按'?'横按进阶':'全部 '+guitarMemoryChordList.length}</button>`).join('')}</div>
 <div class="guitar-memory-controls"><input type="search" aria-label="搜索和弦" placeholder="搜 C、Am、F#m、大七…" value="${esc(guitarChordMemoryQuery)}" oninput="guitarChordMemoryQuery=this.value;document.querySelector('#guitarChordCards').innerHTML=guitarChordMemoryResults()">
 <label class="check"><input type="checkbox" ${guitarChordMemoryHidden?'checked':''} onchange="guitarChordMemoryHidden=this.checked;document.querySelector('#guitarChordCards').innerHTML=guitarChordMemoryResults()">先隐藏指法，想好再展开</label></div>
 <p class="muted">图从左到右6至1弦；×不弹，○空弦。点内1/2/3/4是食指/中指/无名指/小指，T是拇指；长条表示横按。高把位左侧标起始品位。</p>
 <details class="guitar-reference"><summary>容易混淆的名字</summary><p>m＝小三和弦；7＝属七，和maj7（大七）不同；m7＝小七。sus2/sus4用二音/四音替代三音；add9保留三音再加九音。G/B仍是G和弦，最低音弹B。组成音可重复；个别按法会省略五音，卡片已注明。</p></details>
 </div><section id="guitarChordCards" class="guitar-memory-grid" aria-label="和弦指法卡片">${guitarChordMemoryResults()}</section>
 <p class="muted guitar-memory-tip">每天挑2个，先看名字回想手型，再逐根弹清楚；两和弦各4拍，慢速来回换。不要一口气背完。</p>
 <details class="guitar-reference"><summary>延伸参考</summary><a href="https://www.justinguitar.com/chords" target="_blank" rel="noopener noreferrer">JustinGuitar 和弦库 ↗</a></details>`}
render();window.LouiePracticeReady=true;
